additional_options.availability:
{% set lat = states('sensor.ewd108_signed_latitude') | float(none) %}
{% set lon = states('sensor.ewd108_signed_longitude') | float(none) %}
{{ is_state('sensor.ewd108_fix_status', 'Valid') and
   lat is not none and lon is not none and
   -90 <= lat <= 90 and -180 <= lon <= 180 and
   lat != 0 and lon != 0 }}

data.description:
Distance: {{ trip_distance }} km
Start: {{ start_location }}
End: {{ end_location }}
Route: https://www.google.com/maps/dir/?api=1&origin={{ start_location }}&destination={{ end_location }}

matches.content:
- binary_sensor:
  - name: Water Mode Normal Selected
    unique_id: water_mode_normal_selected
    state: "{{ is_state('input_select.water_mode_target', 'Normal') }}"

  - name: Water Mode Pump Filling Selected
    unique_id: water_mode_pump_filling_selected
    state: "{{ is_state('input_select.water_mode_target', 'Pump Filling') }}"

  - name: Water Mode Grid Filling Selected
    unique_id: water_mode_grid_filling_selected
    state: "{{ is_state('input_select.water_mode_target', 'Grid Filling') }}"

  - name: Water Mode Grid Selected
    unique_id: water_mode_grid_selected
    state: "{{ is_state('input_select.water_mode_target', 'Grid') }}"

  sensor:
  - name: "Water Tank Liters"
    unique_id: water_tank_liters_rational
    unit_of_measurement: "L"
    device_class: water
    state_class: measurement
    icon: mdi:water
    availability: >
      {{ states('sensor.water_height')
         not in ['unknown', 'unavailable', 'none', ''] }}
    state: >
      {% set h = states('sensor.water_height') | float(0) %}

      {% if h <= 0 %}
        0
      {% elif h >= 55.8 %}
        100
      {% else %}
        {% set numerator =
          0.668752847 * h
          - 0.0296241152 * h**2
          + 0.00171244226 * h**3
          - 0.0000722092929 * h**4
          + 0.00000103272088 * h**5
        %}

        {% set denominator =
          1
          - 0.00347494792 * h
          - 0.00156556425 * h**2
          + 0.0000292356265 * h**3
        %}

        {{ (numerator / denominator) | round(1) }}
      {% endif %}
  - name: VE.Bus Switch Position Mode
    unique_id: victron_vebus_switch_position_mode
    state: >
      {% set mode = states('select.inverter') | lower %}
      {% if 'charger' in mode %}
        Charger Only
      {% elif 'inverter' in mode %}
        Inverter Only
      {% elif mode == 'on' %}
        On
      {% elif mode == 'off' %}
        Off
      {% else %}
        Unknown
      {% endif %}

  - name: Orion XS Input Battery State of Charge
    unique_id: orion_xs_input_battery_state_of_charge
    unit_of_measurement: "%"
    device_class: battery
    state_class: measurement
    availability: "{{ states('sensor.orion_xs_input_voltage') | float(none) is not none }}"
    state: >
      {% set voltage = states('sensor.orion_xs_input_voltage') | float(none) %}
      {% if voltage is none %}
        {{ none }}
      {% else %}
        {# Approximate 12V lead-acid resting reference: 11.8V empty, 12.8V full; calibrate thresholds for battery chemistry/age and load profile #}
        {% set empty_soc_voltage = 11.8 %}
        {% set full_soc_voltage = 12.8 %}
        {% set soc = ((voltage - empty_soc_voltage) / (full_soc_voltage - empty_soc_voltage)) * 100 %}
        {% if soc < 0 %}
          0
        {% elif soc > 100 %}
          100
        {% else %}
          {{ soc | round(0) }}
        {% endif %}
      {% endif %}

  select:
  - name: Inverter Mode
    unique_id: victron_inverter_mode_control
    state: >
      {% set mode = states('select.inverter') | lower %}
      {% if 'charger' in mode %}
        Charger Only
      {% elif 'inverter' in mode %}
        Inverter Only
      {% elif mode == 'on' %}
        On
      {% elif mode == 'off' %}
        Off
      {% else %}
        Unknown
      {% endif %}
    options: "{{ ['Charger Only', 'Inverter Only', 'On', 'Off'] }}"
    select_option:
    - service: select.select_option
      target:
        entity_id: select.inverter
      data:
        option: >
          {% set map = {
            'Charger Only': 'charger_only',
            'Inverter Only': 'inverter_only',
            'On': 'on',
            'Off': 'off'
          } %}
          {{ map.get(option, option) }}

  switch:
  - name: Inverter Enabled
    unique_id: victron_inverter_power_switch
    state: "{{ states('select.inverter') | lower == 'on' }}"
    turn_on:
    - service: select.select_option
      target:
        entity_id: select.inverter
      data:
        option: "on"
    turn_off:
    - service: select.select_option
      target:
        entity_id: select.inverter
      data:
        option: "off"

- sensor:
  - name: "EWD108 Fix Status"
    unique_id: ewd108_fix_status
    state: >
      {% set v = states('sensor.ewd108_position_valid') | int(-1) %}
      {% if v == 1 %}
        Valid
      {% elif v == 0 %}
        Invalid
      {% else %}
        Unknown
      {% endif %}

  - name: "EWD108 Longitude Direction"
    unique_id: ewd108_longitude_direction
    state: >
      {% set v = states('sensor.ewd108_longitude_direction_raw') | int(0) %}
      {% if v == 69 %}
        E
      {% elif v == 87 %}
        W
      {% else %}
        Unknown
      {% endif %}

  - name: "EWD108 Latitude Direction"
    unique_id: ewd108_latitude_direction
    state: >
      {% set v = states('sensor.ewd108_latitude_direction_raw') | int(0) %}
      {% if v == 78 %}
        N
      {% elif v == 83 %}
        S
      {% else %}
        Unknown
      {% endif %}

  - name: "EWD108 Signed Longitude"
    unique_id: ewd108_signed_longitude
    unit_of_measurement: "°"
    availability: >
      {{ states('sensor.ewd108_longitude') | is_number and
         states('sensor.ewd108_longitude_direction') in ['E', 'W'] }}
    state: >
      {% set lon = states('sensor.ewd108_longitude') | float(0) %}
      {% set dir = states('sensor.ewd108_longitude_direction') %}
      {% if dir == 'W' %}
        {{ -lon }}
      {% else %}
        {{ lon }}
      {% endif %}

  - name: "EWD108 Signed Latitude"
    unique_id: ewd108_signed_latitude
    unit_of_measurement: "°"
    availability: >
      {{ states('sensor.ewd108_latitude') | is_number and
         states('sensor.ewd108_latitude_direction') in ['N', 'S'] }}
    state: >
      {% set lat = states('sensor.ewd108_latitude') | float(0) %}
      {% set dir = states('sensor.ewd108_latitude_direction') %}
      {% if dir == 'S' %}
        {{ -lat }}
      {% else %}
        {{ lat }}
      {% endif %}

  - name: "EWD108 Speed Over Ground kmh"
    unique_id: ewd108_speed_over_ground_kmh
    unit_of_measurement: "km/h"
    device_class: speed
    state_class: measurement
    availability: "{{ states('sensor.ewd108_speed_over_ground') | is_number }}"
    state: >
      {{ (states('sensor.ewd108_speed_over_ground') | float(0) * 1.852) | round(2) }}

  - name: "EWD108 GNSS UTC Time"
    unique_id: ewd108_gnss_utc_time
    device_class: timestamp
    availability: >
      {{ states('sensor.ewd108_year') | int(0) > 2000 and
         states('sensor.ewd108_month') | int(0) in range(1, 13) and
         states('sensor.ewd108_day') | int(0) in range(1, 32) and
         states('sensor.ewd108_hour_utc') | int(-1) in range(0, 24) and
         states('sensor.ewd108_minute_utc') | int(-1) in range(0, 60) and
         states('sensor.ewd108_second_utc') | int(-1) in range(0, 60) }}
    state: >
      {% set y = states('sensor.ewd108_year') | int(0) %}
      {% set mo = states('sensor.ewd108_month') | int(0) %}
      {% set d = states('sensor.ewd108_day') | int(0) %}
      {% set h = states('sensor.ewd108_hour_utc') | int(0) %}
      {% set mi = states('sensor.ewd108_minute_utc') | int(0) %}
      {% set s = states('sensor.ewd108_second_utc') | int(0) %}
      {{ "%04d-%02d-%02dT%02d:%02d:%02d+00:00" | format(y, mo, d, h, mi, s) }}

  - name: "EWD108 Antenna Mode"
    unique_id: ewd108_antenna_mode
    state: >
      {% set v = states('sensor.ewd108_antenna_setting') | int(-1) %}
      {% if v == 0 %}
        Active
      {% elif v == 1 %}
        Passive
      {% else %}
        Unknown
      {% endif %}

  - name: "EWD108 Update Frequency Text"
    unique_id: ewd108_update_frequency_text
    state: >
      {% set v = states('sensor.ewd108_update_frequency') | int(-1) %}
      {% if v == 0 %}
        1 Hz
      {% elif v == 1 %}
        10 Hz
      {% else %}
        Unknown
      {% endif %}

